    async def del_chat_history(self, sn: str):
        response = await self.rapi_getHistory(sn=sn)

        return await self.rapi_delHistory(sn=sn, uptoMsgId=response["results"].get("lastMsgId", 1))

    async def get_error_message(
        self,
        path_url: str,
        response_status_code: Union[str, int],
        response_status_text: str,
    ) -> str:
        return f'{self.env}:{path_url.split("?")[0]}:{response_status_code}:{response_status_text}'

    async def add_task_filter(
        self,
        name: str,
        assignees: [tuple[str, ...], list[str]] = (),
        statuses: [tuple[str, ...], list[str]] = (),
        deadline: Optional[str | datetime] = None,
        subscribed: bool = False,
        withChanges: bool = False,
    ) -> str:
        if deadline is None:
            deadline = datetime.now() + timedelta(days=5)

        for i in range(4):
            response = await self.tasks_filters_add(
                name=name,
                assignees=assignees,
                statuses=statuses,
                deadline=deadline,
                subscribed=subscribed,
                withChanges=withChanges,
            )

            if response["status"]["code"] == 20000:
                filter_id = response["results"]["id"]
                break
            with tracer.start_as_current_span("asyncio.sleep"):
                await asyncio.sleep(i)
        else:
            raise ValueError("Filter ID not found")

        await self.rapi_eventSubscribe(subscriptions=[{"type": "filterList", "data": {"filters": [filter_id]}}])

        return filter_id

    async def iter_task_list(self, filter_name: str = "Все", page_size: int = 20):
        try:
            response = await self.tasks_filters_list()
            filters_list = response["results"]["filters"]

            filter_index = [x["name"] for x in filters_list].index(filter_name)

            filter_id = filters_list[filter_index]["id"]
        except ValueError:
            response = await self.tasks_filters_add(name="Все", statuses=["new", "in_progress", "ready", "rejected"])
            filter_id = response["results"]["id"]

        fetch_tasks = True

        cursor = None

        counter = 0

        while fetch_tasks and counter < 20:
            counter += 1

            response = await self.tasks_list(_filter=filter_id, cursor=cursor, pageSize=page_size)
            result = response["results"]

            cursor = result.get("cursor")

            if not result.get("tasks", []):
                break

            for task in result.get("tasks", []):
                yield task

            if cursor is None:
                break

    async def iter_task_list_for_clean(self, page_size: int = 20):
        response = await self.post(
            "tasks/filters/add",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "name": "Все",
                    "statuses": [
                        "new",
                        "in_progress",
                        "ready",
                        "rejected",
                        "closed",
                    ],
                },
            },
        )
        filter_id = response["results"]["id"]

        fetch_tasks = True

        cursor = None

        counter = 0

        while fetch_tasks and counter < 20:
            counter += 1

            response = await self.tasks_list(_filter=filter_id, cursor=cursor, pageSize=page_size)
            result = response["results"]

            cursor = result.get("cursor")

            if not result.get("tasks", []):
                break

            for task in result.get("tasks", []):
                yield task

            if cursor is None:
                break
        try:
            await self.tasks_filters_delete(filter_id=filter_id)
        except Exception as error:
            self.logger.error(error)

    async def iter_thread_list(self, filter_type: str = "all", page_size: int = 20):
        fetch_tasks = True

        while fetch_tasks:
            response = await self.rapi_thread_feed_get(filter_type=filter_type, pageSize=page_size)
            result = response["results"]

            cursor = result.get("cursor")

            if not result.get("threads", []):
                break

            for thread in result["threads"]:
                yield thread

            if cursor is None:
                break

